import { useState, useEffect, useRef, type ReactNode } from 'react';
import { ArrowUpRight, ArrowRight, ArrowLeft, Globe2, Package, Upload, LayoutGrid, Check, ChevronRight, ChevronDown, Search, SlidersHorizontal, ShieldCheck, CircleCheck, CircleAlert, CircleHelp, Clock3, FileText, MessageSquare, Image, Download, X, Plus, Plane, MapPin, Bell, MoreHorizontal, Sparkles, Languages, CheckCheck, ListChecks, ExternalLink, History, Send, LockKeyhole, RefreshCw, Menu, Link2, BarChart3, Inbox, Camera, AlertTriangle, type LucideIcon } from 'lucide-react';
