import { labels, labelsAr, fieldNames, type PartView, type FieldName, type Checklist, type Compatibility, type Field, type ReadinessStatus } from '../shared/types';

type Page='inventory'|'import'|'part'|'approvals'|'impact';
type Lang='en'|'ar';
type Tab='Record'|'Questions'|'Listing draft'|'Readiness';
interface Impact {label:string;method:string;sampleSize:number;generatedAt:string;metrics:{label:string;prototype:number;manual:number;unit:string;numerator:number;denominator:number}[];preparation:{prototypeMachineMs:number;manualSimulatedSeconds:number;humanReviewTime:string};corrections:{prototypeOpenQuestions:number;manualSimulated:number;note:string};score:{prototype:number;manual:number};rows:{id:string;status:string;questions:number;defectsDisclosed:boolean;compatibility:string}[];session:{sellerCorrections:number;approvals:number;mockPublished:number};}
const statusShort:Record<ReadinessStatus,string>={'Ready for seller review':'Ready for review','Information missing':'Information missing','Specialist review required':'Specialist review'};
const statusAr:Record<string,string>={'Ready for seller review':'جاهزة للمراجعة','Information missing':'معلومات ناقصة','Specialist review required':'مراجعة متخصص','Confirmed':'مؤكّد','Unverified':'غير مؤكّد','Conflicting':'متناقض','Missing':'مفقود'};
const sourceAr:Record<string,string>={'photo':'صورة','spreadsheet':'جدول بيانات','donor record':'سجل السيارة','WhatsApp':'واتساب','Arabic note':'ملاحظة عربية','seller-confirmed':'تأكيد البائع'};
const statusClass=(status:string)=>status==='Ready for seller review'||status==='Confirmed'?'ready':status==='Specialist review required'||status==='Conflicting'?'specialist':'missing';
function Badge({status,ar=false}:{status:string;ar?:boolean}) {return <span className={`badge ${statusClass(status)}`}><span className="status-dot"/>{ar?statusAr[status]||status:statusShort[status as ReadinessStatus]||status}</span>;}
function Button({children,onClick,variant='',disabled=false,type='button',className=''}:{children:ReactNode;onClick?:()=>void;variant?:string;disabled?:boolean;type?:'button'|'submit';className?:string}) {return <button type={type} disabled={disabled} className={`button ${variant} ${className}`} onClick={onClick}>{children}</button>;}
function Empty({title,detail,icon:Icon=Package}:{title:string;detail:string;icon?:LucideIcon}) {return <div className="empty"><Icon size={34}/><h3>{title}</h3><p>{detail}</p></div>;}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:ReactNode}) {useEffect(()=>{const escape=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();};window.addEventListener('keydown',escape);return()=>window.removeEventListener('keydown',escape);},[onClose]);return <div className="modal-backdrop" onClick={onClose}><section className="modal" role="dialog" aria-modal="true" aria-label={title} onClick={e=>e.stopPropagation()}><header><h2>{title}</h2><button className="icon-button" aria-label="Close" onClick={onClose}><X/></button></header>{children}</section></div>;}

export default function App() {
 const [lang,setLang]=useState<Lang>(()=>localStorage.getItem('g2g-language')==='ar'?'ar':'en');const ar=lang==='ar';
 const t=(en:string,arabic:string)=>ar?arabic:en;
 const [parts,setParts]=useState<PartView[]>([]),[checklist,setChecklist]=useState<Checklist|null>(null),[references,setReferences]=useState<Compatibility[]>([]),[health,setHealth]=useState<{provider:string}|null>(null);
 const [page,setPage]=useState<Page>('inventory'),[partId,setPartId]=useState('G2G-001'),[tab,setTab]=useState<Tab>('Record'),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[toast,setToast]=useState<{text:string;error:boolean}|null>(null),[mobile,setMobile]=useState(false),[activity,setActivity]=useState(false),[profile,setProfile]=useState(false),[refModal,setRefModal]=useState(false);
 const refresh=async()=>{const [p,c,r,h]=await Promise.all([api<PartView[]>('/parts'),api<Checklist>('/checklist'),api<Compatibility[]>('/compatibility'),api<{provider:string}>('/health')]);setParts(p);setChecklist(c);setReferences(r);setHealth(h);};
 useEffect(()=>{refresh().catch(e=>setToast({text:e.message,error:true})).finally(()=>setLoading(false));},[]);
 useEffect(()=>{document.documentElement.lang=lang;document.documentElement.dir=ar?'rtl':'ltr';localStorage.setItem('g2g-language',lang);},[lang,ar]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(null),toast.error?12000:5000);return()=>clearTimeout(timer);},[toast]);
 const notify=(text:string,error=false)=>setToast({text,error});
 const run=async(fn:()=>Promise<void>)=>{setBusy(true);try{await fn();}catch(e){notify((e as Error).message,true);}finally{setBusy(false);}};
 const navigate=(p:Page,id?:string,newTab:Tab='Record')=>{setPage(p);if(id)setPartId(id);setTab(newTab);setMobile(false);window.scrollTo({top:0,behavior:'smooth'});};
 const update=(p:PartView)=>setParts(prev=>prev.some(x=>x.id===p.id)?prev.map(x=>x.id===p.id?p:x):[...prev,p]);
 const part=parts.find(p=>p.id===partId);
 const demo=parts.filter(p=>p.batch==='Demo batch · 10 mirrors');
 const ready=demo.filter(p=>p.readiness.status==='Ready for seller review').length;
 const nav:{page:Page;label:string;arabic:string;icon:LucideIcon;count?:number}[]=[{page:'inventory',label:'Inventory',arabic:'المخزون',icon:Package,count:demo.length},{page:'import',label:'Import & inbox',arabic:'الاستيراد والوارد',icon:Inbox},{page:'approvals',label:'Approve & publish',arabic:'الموافقة والنشر',icon:CircleCheck,count:ready},{page:'impact',label:'Impact',arabic:'الأثر',icon:BarChart3}];
 return <div className="app-shell">
   {mobile&&<div className="nav-overlay" onClick={()=>setMobile(false)}/>}
   <aside className={`sidebar ${mobile?'open':''}`}>
     <a className="brand" href="#" onClick={e=>{e.preventDefault();navigate('inventory');}}><span className="brand-mark"><Globe2 size={26}/><ArrowUpRight className="brand-arrow" size={15}/></span><span>Gulf<span className="brand-two">2</span>Global<small>{t('LOCAL PARTS. GLOBAL REACH.','قطع محلية. وصول عالمي.')}</small></span></a>
     <div className="workspace-card"><span className="workspace-avatar">N</span><div><strong>{t('Noor Auto Parts','نور لقطع السيارات')}</strong><small><span className="online-dot"/>{t('Dubai, United Arab Emirates','دبي، الإمارات العربية المتحدة')}</small></div><ChevronDown size={15}/></div>
     <div className="nav-label">{t('SELLER WORKSPACE','مساحة عمل البائع')}</div>
     <nav>{nav.map(item=><button key={item.page} className={`nav-item ${(page===item.page||page==='part'&&item.page==='inventory')?'active':''}`} onClick={()=>navigate(item.page)}><item.icon size={20}/><span>{t(item.label,item.arabic)}</span>{item.count!==undefined&&<span className="nav-count">{item.count}</span>}</button>)}</nav>
     <div className="sidebar-bottom"><div className="corridor-card"><span className="eyebrow">{t('YOUR TRADE CORRIDOR','مسار تجارتك')}</span><div><span className="flag uae"/> UAE <ArrowRight size={16}/> <span className="flag uk"/> UK</div><small>{t('One corridor. Clear next steps.','مسار واحد. خطوات واضحة.')}</small></div><div className="demo-side"><ShieldCheck size={17}/><div><strong>{t('A safe place to start','مكان آمن للبدء')}</strong><span>{t('Synthetic data · Mock publishing','بيانات اصطناعية · نشر تجريبي')}</span></div></div><div className="sidebar-foot">Gulf2Global <span>PROTOTYPE v1.0</span></div></div>
   </aside>
   <div className="main-shell">
     <header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="Open navigation" onClick={()=>setMobile(true)}><Menu size={22}/></button><span>{t('Workspace','مساحة العمل')}</span><ChevronRight size={14}/><strong>{page==='part'?partId:t(nav.find(n=>n.page===page)?.label||'Inventory',nav.find(n=>n.page===page)?.arabic||'المخزون')}</strong></div><div className="top-actions"><span className="sandbox-pill"><span/>{t('Demo workspace','مساحة تجريبية')}</span><button className="language-button" onClick={()=>setLang(ar?'en':'ar')} aria-label="Toggle English / Arabic"><Languages size={16}/>{ar?'English':'العربية'}</button><div className="dropdown-wrap"><button className={`icon-button notification ${activity?'active':''}`} aria-label="Activity notifications" onClick={()=>{setActivity(!activity);setProfile(false);}}><Bell size={19}/><i/></button>{activity&&<div className="top-dropdown"><h3>{t('Recent activity','النشاط الأخير')}</h3>{parts.flatMap(p=>p.audit.map(a=>({...a,part:p.id}))).sort((a,b)=>b.when.localeCompare(a.when)).slice(0,4).map(a=><div key={a.id} className="activity-snippet"><History size={16}/><div><strong>{a.part}</strong><p>{a.action}</p><small>{new Date(a.when).toLocaleString()}</small></div></div>)}</div>}</div><span className="top-divider"/><div className="dropdown-wrap"><button className="profile-button" onClick={()=>{setProfile(!profile);setActivity(false);}}><span className="avatar">N</span><div><strong>{t('Noor','نور')}</strong><small>{t('Seller','البائع')}</small></div><ChevronDown size={14}/></button>{profile&&<div className="top-dropdown"><h3>{t('Noor · fictional seller','نور · بائع خيالي')}</h3><p>{t('Local demo session. No real account, WhatsApp connection or eBay credentials.','جلسة تجريبية محلية. لا حساب حقيقي ولا اتصال بواتساب أو إيباي.')}</p><Badge status="Confirmed" ar={ar}/><p>{t('Seller approval always stays with you.','الموافقة على القوائم تبقى بيدك.')}</p></div>}</div></div></header>
     <main>
     {loading?<div className="loading"><RefreshCw className="spin"/><h2>{t('Opening your workspace…','جارٍ فتح مساحة العمل…')}</h2></div>:!parts.length?<Empty title="Workspace unavailable" detail="Start the backend with npm run dev, then refresh."/>:<>
       {page==='inventory'&&<Inventory parts={parts} ar={ar} t={t} navigate={navigate} busy={busy}/>}
       {page==='import'&&<ImportPage parts={parts} initialId={partId} provider={health?.provider||'mock'} ar={ar} t={t} busy={busy} run={run} refresh={refresh} notify={notify} openReferences={()=>setRefModal(true)} references={references} navigate={navigate}/>}
       {page==='part'&&part&&<PartDetail part={part} tab={tab} setTab={setTab} ar={ar} t={t} busy={busy} run={run} update={update} notify={notify} checklist={checklist!} navigate={navigate} openReferences={()=>setRefModal(true)}/>}
       {page==='approvals'&&<Approvals parts={parts} initialId={partId} ar={ar} t={t} busy={busy} run={run} update={update} notify={notify} navigate={navigate}/>}
       {page==='impact'&&<ImpactPage ar={ar} t={t}/>}
     </>}
     </main>
     <footer className="main-footer"><span><ShieldCheck size={14}/>{t('Evidence first. Seller approved. Never invented.','الأدلة أولاً. بموافقة البائع. دون اختلاق.')}</span><span>{t('TEST checklist only · Not legal or customs clearance','قائمة اختبار فقط · ليست تصريحاً قانونياً أو جمركياً')}</span></footer>
   </div>
   {toast&&<div className={`toast ${toast.error?'error':''}`} role="alert">{toast.error?<CircleAlert size={21}/>:<CircleCheck size={21}/>}<span>{toast.text}</span><button className="icon-button" aria-label="Dismiss" onClick={()=>setToast(null)}><X size={17}/></button></div>}
   {refModal&&<ReferenceModal ar={ar} t={t} busy={busy} run={run} refresh={refresh} notify={notify} onClose={()=>setRefModal(false)} references={references}/>}
 </div>;
}
type Translate=(en:string,ar:string)=>string;
type Navigate=(page:Page,id?:string,tab?:Tab)=>void;
type Run=(fn:()=>Promise<void>)=>Promise<void>;
interface Actions {busy:boolean;run:Run;notify:(text:string,error?:boolean)=>void;}

function Inventory({parts,ar,t,navigate}:{parts:PartView[];ar:boolean;t:Translate;navigate:Navigate;busy:boolean}) {
 const [filter,setFilter]=useState('all'),[search,setSearch]=useState(''),[batch,setBatch]=useState('demo'),[selected,setSelected]=useState<string[]>([]),[filtersOpen,setFiltersOpen]=useState(false),[issueOnly,setIssueOnly]=useState(false);
 const sample=parts.filter(p=>batch==='all'||p.batch==='Demo batch · 10 mirrors');
 const counts={ready:sample.filter(p=>p.readiness.status==='Ready for seller review').length,missing:sample.filter(p=>p.readiness.status==='Information missing').length,specialist:sample.filter(p=>p.readiness.status==='Specialist review required').length};
 const visible=sample.filter(p=>(filter==='all'||statusClass(p.readiness.status)===filter)&&(!issueOnly||p.readiness.missingCount>0||p.readiness.conflictCount>0)&&`${p.id} ${Object.values(p.fields).map(f=>f.value||'').join(' ')}`.toLowerCase().includes(search.toLowerCase()));
 const statItems=[{label:t('Parts in your inventory','القطع في مخزونك'),number:sample.length,icon:Package,className:'neutral',note:t('Used side-view mirrors only','مرايا جانبية مستعملة فقط'),filter:'all'},{label:t('Ready for seller review','جاهزة لمراجعة البائع'),number:counts.ready,icon:CircleCheck,className:'ready',note:t('Clear evidence. Your approval next.','أدلة واضحة. موافقتك هي التالية.'),filter:'ready'},{label:t('Information missing','معلومات ناقصة'),number:counts.missing,icon:CircleHelp,className:'missing',note:t('A few answers make a difference.','بعض الإجابات تصنع الفارق.'),filter:'missing'},{label:t('Specialist review required','مراجعة متخصص مطلوبة'),number:counts.specialist,icon:ShieldCheck,className:'specialist',note:t('Conflicts that need a closer look.','تناقضات تحتاج تدقيقاً.'),filter:'specialist'}];
 return <div className="page inventory-page">
   <div className="page-heading"><div><div className="eyebrow"><span className="tiny-dot"/>{t('YOUR INVENTORY, CONNECTED','مخزونك، مترابط')}</div><h1>{t('Local parts. Global possibilities.','قطع محلية. فرص عالمية.')}</h1><p>{t('Turn what you know into listings you can stand behind.','حوّل معلوماتك إلى قوائم يمكنك الوثوق بها.')}</p></div><Button onClick={()=>navigate('import')}><Plus size={18}/>{t('Import inventory','استيراد المخزون')}</Button></div>
   <section className="journey-banner"><div className="journey-copy"><span className="light-eyebrow"><Sparkles size={13}/>{t('FROM FRAGMENTS TO CONFIDENCE','من معلومات متفرقة إلى الثقة')}</span><h2>{t('A clearer path from Dubai to the UK.','طريق أوضح من دبي إلى المملكة المتحدة.')}</h2><p>{t('Bring your photos, notes and records together. We find the gaps.','اجمع صورك وملاحظاتك وسجلاتك. نكتشف المعلومات الناقصة.')}<br/>{t('You confirm the facts. Nothing gets invented.','أنت تؤكد الحقائق. لا شيء يُختلق.')}</p><button className="text-link light" onClick={()=>navigate('part','G2G-002','Questions')}>{t('Explore the difficult-part demo','استكشف تجربة القطعة الصعبة')}<ArrowUpRight size={16}/></button></div><div className="route-art" aria-label="Dubai UAE to United Kingdom corridor"><div className="route-orbit orbit-one"/><div className="route-orbit orbit-two"/><div className="route-line"/><div className="route-point dubai"><span className="location-icon"><MapPin size={20}/></span><strong>Dubai</strong><small>UNITED ARAB EMIRATES</small></div><span className="route-plane"><Plane size={29}/></span><div className="route-point london"><span className="location-icon"><Globe2 size={20}/></span><strong>United Kingdom</strong><small>YOUR NEXT MARKET</small></div><div className="route-tag"><ShieldCheck size={13}/>{t('Evidence travels with every part','الأدلة ترافق كل قطعة')}</div></div></section>
   <section className="stats-grid">{statItems.map(s=><button key={s.filter} className="stat-card" onClick={()=>setFilter(s.filter)}><div className="stat-top"><span>{s.label}</span><span className={`stat-icon ${s.className}`}><s.icon size={18}/></span></div><strong>{String(s.number).padStart(2,'0')}</strong><small>{s.note}</small></button>)}</section>
   <section className="inventory-card"><div className="section-title"><div><h2>{t('Inventory','المخزون')} <span className="number-tag">{sample.length}</span></h2><p>{t('Every part has a story. Every field has a source.','لكل قطعة قصة. ولكل حقل مصدر.')}</p></div><div className="table-heading-actions"><select aria-label="Inventory sample" value={batch} onChange={e=>{setBatch(e.target.value);setSelected([]);}}><option value="demo">{t('Demo batch · 10 mirrors','دفعة تجريبية · 10 مرايا')}</option><option value="all">{t('All 20 + imported records','كل الـ20 والسجلات المستوردة')}</option></select><button className="icon-button" aria-label="Export visible inventory" onClick={()=>download('gulf2global-inventory.json',visible)}><Download size={18}/></button></div></div>
    <div className="table-toolbar"><div className="filter-tabs">{[{id:'all',label:t('All parts','كل القطع'),n:sample.length},{id:'ready',label:t('Ready for review','جاهزة للمراجعة'),n:counts.ready},{id:'missing',label:t('Missing info','معلومات ناقصة'),n:counts.missing},{id:'specialist',label:t('Specialist review','مراجعة متخصص'),n:counts.specialist}].map(f=><button key={f.id} className={filter===f.id?'active':''} onClick={()=>setFilter(f.id)}>{f.label}<span>{f.n}</span></button>)}</div><div className="search-actions"><label className="search-input"><Search size={16}/><input aria-label="Search parts" placeholder={t('Search parts…','ابحث عن قطعة…')} value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button aria-label="Clear search" onClick={()=>setSearch('')}><X size={13}/></button>}</label><button className={`filter-button ${filtersOpen?'active':''}`} onClick={()=>setFiltersOpen(!filtersOpen)}><SlidersHorizontal size={16}/>{t('Filters','الفلاتر')}</button></div></div>
    {filtersOpen&&<div className="filter-panel"><label><input type="checkbox" checked={issueOnly} onChange={e=>setIssueOnly(e.target.checked)}/>{t('Only parts with missing information or conflicts','القطع ذات المعلومات الناقصة أو المتناقضة فقط')}</label><button className="text-link" onClick={()=>{setIssueOnly(false);setSearch('');setFilter('all');}}>{t('Reset filters','إعادة ضبط')}</button></div>}
    {selected.length>0&&<div className="selection-bar"><CheckCheck size={16}/>{selected.length} {t('parts selected','قطع محددة')}<button className="text-link" onClick={()=>navigate('approvals',selected[0])}>{t('Review selected','مراجعة المحدد')}<ArrowRight size={14}/></button><button className="text-link" onClick={()=>download('selected-inventory.json',parts.filter(p=>selected.includes(p.id)))}>{t('Export selected','تصدير المحدد')}</button></div>}
    <div className="table-scroll"><table className="inventory-table"><thead><tr><th className="checkbox-cell"><input type="checkbox" aria-label="Select all visible parts" checked={visible.length>0&&visible.every(p=>selected.includes(p.id))} onChange={e=>setSelected(e.target.checked?visible.map(p=>p.id):[])}/></th><th>{t('PART','القطعة')}</th><th>{t('DONOR VEHICLE','السيارة المانحة')}<CircleHelp size={12}/></th><th>{t('READINESS','الجاهزية')}</th><th>{t('INFORMATION GAPS','نقص المعلومات')}</th><th>{t('ASKING PRICE','السعر')}</th><th/></tr></thead><tbody>{visible.map(p=><tr key={p.id} onClick={()=>navigate('part',p.id)}><td className="checkbox-cell" onClick={e=>e.stopPropagation()}><input type="checkbox" aria-label={`Select ${p.id}`} checked={selected.includes(p.id)} onChange={e=>setSelected(prev=>e.target.checked?[...prev,p.id]:prev.filter(id=>id!==p.id))}/></td><td><div className="part-cell"><div className="part-thumbnail">{p.photos[0]?<img src={p.photos[0]} alt="Synthetic mirror placeholder"/>:<Package size={22}/>}</div><div><strong>{p.fields.manufacturer.value||t('Unidentified','غير محدد')} {p.fields.donor_model.value||''} {t('mirror','مرآة')}</strong><small><span className="mono">{p.id}</span><span className="cell-dot">·</span>{p.fields.side.status==='Conflicting'?t('Position conflict','تعارض الجهة'):p.fields.side.value||t('Position missing','الجهة مفقودة')}</small></div></div></td><td><strong className="table-plain">{p.fields.donor_make.value} {p.fields.donor_model.value}</strong><small className={p.fields.donor_year.status==='Conflicting'?'conflict-text':''}>{p.fields.donor_year.status==='Conflicting'?<><CircleAlert size={12}/>2017 / 2018 · {t('Conflict','تعارض')}</>:<>{p.fields.donor_year.value} <span className="donor-only">· {t('Record only','من السجل فقط')}</span></>}</small></td><td><Badge status={p.readiness.status} ar={ar}/></td><td>{p.readiness.missingCount||p.readiness.conflictCount?<span className="gap-count"><span className={`gap-icon ${p.readiness.conflictCount?'red':''}`}><CircleHelp size={13}/></span>{p.readiness.missingCount} {t('missing','ناقصة')}{p.readiness.conflictCount>0&&<span className="conflict-mini">+ {p.readiness.conflictCount} {t('conflict','تعارض')}</span>}</span>:<span className="complete-cell"><Check size={14}/>{t('Complete','مكتملة')}</span>}</td><td className="price-cell">£{p.fields.asking_price.value||'—'}</td><td><button className="row-arrow" aria-label={`Open ${p.id}`}><ArrowUpRight size={17}/></button></td></tr>)}</tbody></table></div>
    {!visible.length&&<Empty title={t('No matching parts','لا توجد قطع مطابقة')} detail={t('Try another search or reset your filters.','جرّب بحثاً آخر أو أعد ضبط الفلاتر.')}/>}
    <div className="table-footer"><span>{t('Showing','عرض')} {visible.length} {t('of','من')} {sample.length} {t('parts','قطع')} <span className="foot-separator">|</span> {t('All data is fictional','كل البيانات خيالية')}</span><span><span className="tiny-dot"/>{t('Changes saved automatically','التغييرات محفوظة تلقائياً')}</span></div>
   </section>
   <div className="trust-strip"><span className="trust-icon"><ShieldCheck size={22}/></span><div><strong>{t('Confident listings start with honest gaps.','القوائم الموثوقة تبدأ بتوضيح النواقص.')}</strong><p>{t('Donor vehicle ≠ compatibility. Unknown details stay unknown until you confirm them.','السيارة المانحة لا تعني التوافق. التفاصيل المجهولة تبقى كذلك حتى تأكيدها.')}</p></div><button className="text-link" onClick={()=>navigate('impact')}>{t('See how we measure trust','كيف نقيس الثقة')}<ArrowRight size={15}/></button></div>
 </div>;
}

function ImportPage({parts,initialId,provider,ar,t,busy,run,refresh,notify,openReferences,references,navigate}:{parts:PartView[];initialId:string;provider:string;ar:boolean;t:Translate;refresh:()=>Promise<void>;openReferences:()=>void;references:Compatibility[];navigate:Navigate}&Actions) {
 const [mode,setMode]=useState('spreadsheet'),[files,setFiles]=useState<File[]>([]),[notes,setNotes]=useState(''),[partId,setPartId]=useState(initialId),[report,setReport]=useState<{parts:string[];observations:number;warnings:string[]}|null>(null),[drag,setDrag]=useState(false);
 const input=useRef<HTMLInputElement>(null);
 const modes=[{id:'spreadsheet',icon:FileText,title:t('Inventory spreadsheet','جدول المخزون'),detail:'CSV / JSON'},{id:'donor',icon:Package,title:t('Donor records','سجلات السيارة المانحة'),detail:'CSV / JSON'},{id:'photos',icon:Camera,title:t('Part photos','صور القطعة'),detail:'JPG / PNG / WebP'},{id:'notes',icon:MessageSquare,title:t('WhatsApp & Arabic notes','واتساب وملاحظات عربية'),detail:t('Paste text · EN / AR','نص · إنجليزي / عربي')}];
 const submit=()=>run(async()=>{const data=new FormData();data.append('mode',mode);data.append('partId',partId);data.append('notes',notes);files.forEach(f=>data.append('files',f));const result=await api<typeof report>('/import',{method:'POST',body:data});setReport(result);await refresh();setFiles([]);setNotes('');notify(t('Sources merged. Review unverified fields and any conflicts.','تم دمج المصادر. راجع الحقول غير المؤكدة والتناقضات.'));});
 return <div className="page"><div className="page-heading"><div><div className="eyebrow">{t('BRING THE PIECES TOGETHER','اجمع المعلومات المتفرقة')}</div><h1>{t('Import & inbox','الاستيراد والوارد')}</h1><p>{t('One part, many sources. Nothing gets lost in the conversation.','قطعة واحدة، مصادر متعددة. لا تضيع أي معلومة.')}</p></div><span className="outline-tag"><Sparkles size={15}/>{provider==='mock'?t('Mock extraction','استخراج تجريبي'):provider}</span></div>
 <div className="info-banner"><ShieldCheck size={19}/><p>{t('Only synthetic, non-hazardous side-view mirrors. Sources merge by explicit part ID—not appearance. All extracted values remain unverified until you confirm them.','مرايا جانبية اصطناعية غير خطرة فقط. يُدمج المصدر برقم القطعة الصريح، لا بالشكل. القيم المستخرجة غير مؤكدة حتى تأكيدك.')}</p></div>
 <div className="import-layout"><section className="panel"><div className="panel-header"><h2>{t('Add your sources','أضف مصادرك')}</h2><span className="number-tag">01</span></div><div className="source-mode-grid">{modes.map(m=><button key={m.id} className={`source-mode ${mode===m.id?'selected':''}`} onClick={()=>{setMode(m.id);setFiles([]);setReport(null);}}><m.icon size={23}/><strong>{m.title}</strong><small>{m.detail}</small>{mode===m.id&&<CircleCheck size={16} className="mode-check"/>}</button>)}</div><label className="form-label">{t('Attach to an existing part','إرفاق بقطعة موجودة')}<select value={partId} onChange={e=>setPartId(e.target.value)}><option value="">{t('Use part_id from each CSV/JSON row','استخدم part_id لكل صف')}</option>{parts.map(p=><option key={p.id} value={p.id}>{p.id} · {p.fields.donor_make.value} {p.fields.donor_model.value}</option>)}</select></label><p className="field-hint">{t('Required for photos and notes. For files, each row’s part_id takes priority. New IDs create separate records.','مطلوب للصور والملاحظات. رقم part_id في الصف له الأولوية. الأرقام الجديدة تُنشئ سجلات منفصلة.')}</p>
 {mode!=='notes'&&<><input ref={input} type="file" multiple accept={mode==='photos'?'.png,.jpg,.jpeg,.webp':'.csv,.json'} className="hidden" onChange={e=>setFiles(Array.from(e.target.files||[]))}/><button className={`upload-drop ${drag?'drag':''}`} onClick={()=>input.current?.click()} onDragOver={e=>{e.preventDefault();setDrag(true);}} onDragLeave={()=>setDrag(false)} onDrop={e=>{e.preventDefault();setDrag(false);setFiles(Array.from(e.dataTransfer.files));}}><span className="upload-icon"><Upload size={25}/></span><strong>{t('Drop your files here, or click to browse','اسحب الملفات هنا أو انقر للاختيار')}</strong><small>{t('Up to 12 files · 8 MB per file','حتى 12 ملفاً · 8 ميجابايت لكل ملف')}</small></button><div className="file-list">{files.map((f,i)=><div key={i}><FileText size={16}/><span>{f.name}</span><small>{Math.round(f.size/1024)} KB</small><button className="icon-button" aria-label={`Remove ${f.name}`} onClick={()=>setFiles(files.filter((_,j)=>i!==j))}><X size={15}/></button></div>)}</div></>}
 <label className="form-label">{mode==='notes'?t('Paste WhatsApp messages or Arabic notes','الصق رسائل واتساب أو ملاحظات عربية'):t('Additional notes (optional)','ملاحظات إضافية (اختياري)')}<textarea rows={mode==='notes'?7:3} dir="auto" placeholder={t('For mock extraction, use explicit lines:\npart_number: SYN-TO-2101-R\ndefects: Damaged mounting tab\nالاختبار: لم يتم الاختبار','للاستخراج التجريبي، استخدم أسطراً صريحة:\nرقم القطعة: SYN-TO-2101-R\nالعيوب: لسان تثبيت مكسور\nالاختبار: لم يتم الاختبار')} value={notes} onChange={e=>setNotes(e.target.value)}/></label><div className="form-bottom"><span><LockKeyhole size={14}/>{t('No real WhatsApp connection','لا اتصال حقيقي بواتساب')}</span><Button disabled={busy||!files.length&&!notes.trim()} onClick={submit}>{busy?<RefreshCw size={16} className="spin"/>:<Sparkles size={16}/>} {t('Extract & merge','استخراج ودمج')}</Button></div>
 </section><aside className="import-aside"><section className="panel"><h3>{t('Try the sample packet','جرّب حزمة البيانات')}</h3><p>{t('20 fictional mirrors. English and Arabic notes. Deliberately imperfect records.','20 مرآة خيالية، ملاحظات إنجليزية وعربية، وسجلات ناقصة عمداً.')}</p>{[{file:'inventory.csv',label:t('Inventory spreadsheet','جدول المخزون')},{file:'donor_records.json',label:t('Donor records','سجلات السيارة')},{file:'whatsapp_en.txt',label:t('English messages','رسائل إنجليزية')},{file:'whatsapp_ar.txt',label:t('Arabic messages','رسائل عربية')}].map(s=><a key={s.file} className="sample-link" href={`/api/samples/${s.file}`} download><FileText size={16}/>{s.label}<Download size={15}/></a>)}<small>{t('The demo inventory is already seeded. Importing merges sources, never duplicates an explicit ID.','المخزون التجريبي موجود مسبقاً. الاستيراد يدمج المصادر ولا يكرر الرقم الصريح.')}</small></section><section className="panel reference-panel"><span className="stat-icon ready"><Link2 size={20}/></span><h3>{t('Independent compatibility','التوافق المستقل')}</h3><p>{t('Fitment never comes from a donor vehicle or a photo. Only your approved reference dataset.','لا يُستنتج التوافق من السيارة المانحة أو الصورة. فقط من بيانات المرجع المعتمد.')}</p><span className="outline-tag">{references.length} {t('approved reference rows','صفوف مرجعية')}</span><Button variant="secondary" onClick={openReferences}><Upload size={16}/>{t('Manage reference dataset','إدارة بيانات المرجع')}</Button></section></aside></div>
 {report&&<section className="panel import-report"><div className="panel-header"><h2><CircleCheck size={21}/>{t('Sources received','تم استلام المصادر')}</h2><span>{report.observations} {t('observations','ملاحظات مستخرجة')}</span></div>{report.warnings.map((w,i)=><div key={i} className="warning-line"><CircleAlert size={16}/><p>{w}</p></div>)}<div className="report-parts">{report.parts.map(id=><Button key={id} variant="secondary" onClick={()=>navigate('part',id,'Record')}>{id}<ArrowUpRight size={15}/></Button>)}</div></section>}
 <section className="panel inbox-section"><div className="panel-header"><h2>{t('Recent source activity','نشاط المصادر الأخير')}</h2><History size={18}/></div>{parts.flatMap(p=>p.audit.filter(a=>a.action.includes('Imported')).map(a=>({...a,part:p.id}))).sort((a,b)=>b.when.localeCompare(a.when)).slice(0,6).map(a=><div className="inbox-row" key={a.id}><span className="stat-icon neutral"><Inbox size={18}/></span><div><strong>{a.part}</strong><p>{a.action}</p></div><small>{new Date(a.when).toLocaleString()}</small><button className="icon-button" onClick={()=>navigate('part',a.part)} aria-label="Open imported record"><ArrowUpRight size={17}/></button></div>)}{!parts.some(p=>p.audit.some(a=>a.action.includes('Imported')))&&<div className="inbox-row"><span className="stat-icon ready"><CheckCheck size={18}/></span><div><strong>{t('Synthetic sample packet loaded','تم تحميل الحزمة الاصطناعية')}</strong><p>{t('20 records · photos, spreadsheet, donor records and EN/AR notes','20 سجلاً · صور وجدول وسجلات سيارة وملاحظات إنجليزية وعربية')}</p></div><span className="outline-tag">{t('Seed data','بيانات تجريبية')}</span></div>}</section>
 </div>;
}

function PartDetail({part,tab,setTab,ar,t,busy,run,update,notify,checklist,navigate,openReferences}:{part:PartView;tab:Tab;setTab:(tab:Tab)=>void;ar:boolean;t:Translate;update:(p:PartView)=>void;checklist:Checklist;navigate:Navigate;openReferences:()=>void}&Actions) {
 const [editing,setEditing]=useState<FieldName|null>(null),[photoIndex,setPhotoIndex]=useState(0),[auditOpen,setAuditOpen]=useState(false);
 return <div className="page detail-page"><button className="text-link back-link" onClick={()=>navigate('inventory')}><ArrowLeft size={16}/>{t('Back to inventory','العودة إلى المخزون')}</button><div className="page-heading"><div><div className="eyebrow">{part.id} <span>·</span> {t('EVIDENCE-BACKED PART RECORD','سجل قطعة مدعوم بالأدلة')}</div><h1>{part.fields.donor_make.value} {part.fields.donor_model.value} {t('side-view mirror','مرآة جانبية')}</h1><p>{t('Record the truth once. Keep every next step in sync.','سجّل الحقيقة مرة واحدة. تبقى كل الخطوات متزامنة.')}</p></div><Button variant="secondary" onClick={()=>navigate('approvals',part.id)}><CircleCheck size={17}/>{t('Review & approve','مراجعة وموافقة')}</Button></div>
 <div className="part-summary"><div className="detail-photo">{part.photos.length>0?<img src={part.photos[photoIndex]||part.photos[0]} alt={t('Part source image (seed images are synthetic placeholders)','صورة مصدر القطعة (الصور التجريبية اصطناعية)')}/>:<Empty icon={Camera} title={t('No photo attached','لا صورة مرفقة')} detail={t('Upload a source photo.','ارفع صورة للمصدر.')}/>}<span>{part.photos.length>0?`${t('Source photo','صورة المصدر')} ${Math.min(photoIndex+1,part.photos.length)}/${part.photos.length}`:t('Photo missing','الصورة مفقودة')}</span>{part.photos.length>1&&<div className="photo-controls"><button aria-label="Previous photo" onClick={()=>setPhotoIndex(i=>(i-1+part.photos.length)%part.photos.length)}><ArrowLeft size={14}/></button><button aria-label="Next photo" onClick={()=>setPhotoIndex(i=>(i+1)%part.photos.length)}><ArrowRight size={14}/></button></div>}</div><div className="summary-info"><Badge status={part.readiness.status} ar={ar}/><h2>{part.fields.part_number.status==='Confirmed'?part.fields.part_number.value:t('Identifier needs confirmation','الرقم يحتاج تأكيداً')}</h2><div className="summary-meta"><span><MapPin size={15}/>{part.fields.storage_location.value||t('Location missing','الموقع مفقود')}</span><span><Package size={15}/>{part.fields.side.value||t('Position unverified','الجهة غير مؤكدة')} · {t('Used','مستعملة')}</span><span><Clock3 size={15}/>{part.fields.testing_status.status==='Confirmed'?part.fields.testing_status.value:t('Not tested','لم يتم الاختبار')}</span></div><div className="summary-bottom"><span><strong>{part.readiness.missingCount}</strong> {t('information gaps','معلومات ناقصة')} <span>·</span> <strong>{part.readiness.conflictCount}</strong> {t('conflicts','تناقضات')}</span><span className="outline-tag">{t('Revision','الإصدار')} {part.revision}</span></div></div><div className="evidence-promise"><ShieldCheck size={25}/><strong>{t('Nothing silently assumed.','لا افتراضات خفية.')}</strong><p>{t('Sources stay attached. Uncertainty stays visible. Your corrections flow through the draft and checklist.','المصادر محفوظة. عدم اليقين واضح. تصحيحاتك تُحدّث المسودة والقائمة.')}</p></div></div>
 <div className="detail-tabs">{(['Record','Questions','Listing draft','Readiness'] as Tab[]).map((name,i)=>{const Icon=[FileText,MessageSquare,LayoutGrid,ListChecks][i];return <button key={name} onClick={()=>setTab(name)} className={tab===name?'active':''}><Icon size={17}/>{t(name,['السجل','الأسئلة','مسودة القائمة','الجاهزية'][i])}{name==='Questions'&&<span className="number-tag">{part.questions.length}</span>}</button>;})}</div>
 {tab==='Record'&&<div className="record-layout"><section className="panel record-panel"><div className="panel-header"><div><h2>{t('One record. Every source.','سجل واحد. كل المصادر.')}</h2><p>{t('Click a field to confirm or correct it. All changes are logged.','انقر على الحقل لتأكيده أو تصحيحه. كل التغييرات مسجلة.')}</p></div><span className="outline-tag"><CheckCheck size={14}/>{t('Auto-saved','محفوظ تلقائياً')}</span></div><div className="fields-list">{fieldNames.map(key=><button key={key} className={`field-row ${part.fields[key].status==='Conflicting'?'conflict-row':''}`} onClick={()=>setEditing(key)}><div className="field-name">{ar?labelsAr[key]:labels[key]}</div><div className="field-value"><strong dir="auto">{part.fields[key].value||t('Not recorded','غير مسجل')}</strong>{part.fields[key].status==='Conflicting'&&<span className="conflict-options">{[...new Set(part.fields[key].evidence.map(e=>e.value))].join(' ↔ ')}</span>}<small><SourceIcon source={part.fields[key].source}/>{part.fields[key].source?(ar?sourceAr[part.fields[key].source]:part.fields[key].source):t('No source yet','لا مصدر بعد')}{part.fields[key].source&&<><span>·</span>{Math.round(part.fields[key].confidence*100)}% {t('confidence','ثقة')}</>}</small></div><Badge status={part.fields[key].status} ar={ar}/><ChevronRight size={15}/></button>)}</div></section><aside><section className="panel source-notes"><h3><MessageSquare size={18}/>{t('Original messages','الرسائل الأصلية')}</h3>{part.notes.map((n,i)=><div className="note-card" key={i}><span><SourceIcon source={n.source}/>{ar?sourceAr[n.source]||n.source:n.source}</span><p dir="auto">{n.text}</p><small>{n.reference}</small></div>)}</section><div className="info-note"><CircleHelp size={18}/><p>{t('Seed photos are illustrative placeholders. They do not prove authenticity, fitment or functionality.','الصور التجريبية توضيحية. لا تثبت الأصالة أو التوافق أو الوظيفة.')}</p></div></aside></div>}
 {tab==='Questions'&&<Questions part={part} ar={ar} t={t} busy={busy} run={run} update={update} notify={notify} openEdit={setEditing} navigate={navigate}/>}
 {tab==='Listing draft'&&<Listing part={part} ar={ar} t={t} busy={busy} run={run} update={update} notify={notify} openReferences={openReferences}/>}
 {tab==='Readiness'&&<Readiness part={part} checklist={checklist} ar={ar} t={t} onQuestion={()=>setTab('Questions')} navigate={navigate}/>}
 <section className="panel audit-panel"><button className="audit-heading" onClick={()=>setAuditOpen(!auditOpen)}><History size={18}/><strong>{t('Audit trail','سجل التغييرات')}</strong><span className="number-tag">{part.audit.length}</span><ChevronDown size={17} className={auditOpen?'rotated':''}/></button>{auditOpen&&<div className="audit-list">{[...part.audit].reverse().map(a=><div className="audit-item" key={a.id}><span className="audit-dot"/><div><strong>{a.action}</strong><p>{a.who} · {new Date(a.when).toLocaleString()} · {a.source}</p>{a.field&&<div className="audit-change"><span>{ar?labelsAr[a.field as FieldName]:labels[a.field as FieldName]}</span><del>{typeof a.old==='string'?a.old:JSON.stringify(a.old)}</del><ArrowRight size={14}/><ins>{String(a.new)}</ins></div>}</div></div>)}</div>}</section>
 {editing&&<FieldModal key={`${part.id}-${editing}-${part.revision}`} part={part} field={editing} ar={ar} t={t} busy={busy} run={run} update={update} notify={notify} onClose={()=>setEditing(null)}/>}
 </div>;
}
function SourceIcon({source}:{source:string|null}) {const Icon=source==='photo'?Image:source==='seller-confirmed'?CheckCheck:source==='WhatsApp'||source==='Arabic note'?MessageSquare:FileText;return <Icon size={12}/>;}

function FieldModal({part,field,ar,t,busy,run,update,notify,onClose}:{part:PartView;field:FieldName;ar:boolean;t:Translate;update:(p:PartView)=>void;onClose:()=>void}&Actions) {
 const f=part.fields[field];const [value,setValue]=useState(field==='condition'?'Used':f.value||''),[testNote,setTestNote]=useState('');
 const save=()=>run(async()=>{const updated=await api<PartView>(`/parts/${part.id}/fields/${field}`,{method:'PATCH',body:JSON.stringify({value,testNote,revision:part.revision})});update(updated);notify(t('Confirmed. Record → draft → checklist updated. Approval reset.','تم التأكيد. السجل والمسودة والقائمة مُحدّثة. أُعيد ضبط الموافقة.'));onClose();});
 return <Modal title={ar?labelsAr[field]:labels[field]} onClose={onClose}><div className="modal-body"><div className="modal-subtitle"><span className="mono">{part.id}</span><Badge status={f.status} ar={ar}/></div><div className="evidence-history"><h4>{t('Source evidence','أدلة المصدر')}</h4>{f.evidence.length?f.evidence.map((e,i)=><div key={i}><span className="source-label"><SourceIcon source={e.source}/>{ar?sourceAr[e.source]:e.source}</span><strong dir="auto">{e.value}</strong><small>{e.reference} · {Math.round(e.confidence*100)}%</small></div>):<p>{t('No evidence recorded yet. Do not estimate or guess.','لا دليل مسجل بعد. لا تقدّر أو تخمّن.')}</p>}</div>{field==='part_number'&&<div className="warning-line"><Camera size={18}/><p>{t('Unreadable digits? Request a clearer label photo. Enter only a fully readable identifier you have verified.','أرقام غير واضحة؟ اطلب صورة أوضح. أدخل الرقم المقروء الذي تحققت منه فقط.')}</p></div>}
 <label className="form-label">{t('Your confirmed answer','إجابتك المؤكدة')}{field==='side'?<select value={value} onChange={e=>setValue(e.target.value)}><option value="">{t('Choose position','اختر الجهة')}</option><option value="Left">{t('Left','يسار')}</option><option value="Right">{t('Right','يمين')}</option></select>:field==='testing_status'?<select value={value} onChange={e=>setValue(e.target.value)}><option value="">{t('Choose recorded test status','اختر حالة الاختبار')}</option>{['Not tested','Seller tested: adjustment motor only','Seller tested: glass inspection only','Seller tested: folding motor only'].map(v=><option key={v} value={v}>{v==='Not tested'?t(v,'لم يتم الاختبار'):v}</option>)}</select>:field==='condition'?<select value="Used" onChange={()=>setValue('Used')}><option value="Used">{t('Used','مستعملة')}</option></select>:<textarea rows={field==='defects'||field==='included_components'?3:2} dir="auto" value={value} onChange={e=>setValue(e.target.value)} placeholder={field==='packed_dimensions'?'35 x 24 x 19':field==='packed_weight'?'2.4':t('Only details you can verify','التفاصيل التي يمكنك التحقق منها فقط')}/>}</label>
 <label className="form-label">{field==='testing_status'&&value!=='Not tested'?t('Test method, date and result (required)','طريقة الاختبار وتاريخه ونتيجته (مطلوب)'):t('Evidence / correction note (optional)','ملاحظة الدليل أو التصحيح (اختياري)')}<textarea dir="auto" rows={2} value={testNote} onChange={e=>setTestNote(e.target.value)} placeholder={t('What record or inspection supports this answer?','ما السجل أو الفحص الذي يدعم هذه الإجابة؟')}/></label><div className="info-note"><ShieldCheck size={16}/><p>{t('Saved as seller-confirmed, with your name and time. Any existing approval is invalidated. Recorded damage cannot be removed.','يُحفظ كتأكيد البائع مع اسمك والوقت. تُلغى الموافقة السابقة. لا يمكن إزالة الضرر المسجل.')}</p></div><div className="modal-actions"><Button variant="secondary" onClick={onClose}>{t('Cancel','إلغاء')}</Button><Button disabled={busy||!value.trim()} onClick={save}>{busy?<RefreshCw size={16} className="spin"/>:<Check size={16}/>} {t('Confirm & update','تأكيد وتحديث')}</Button></div></div></Modal>;
}

function Questions({part,ar,t,busy,run,notify,openEdit,navigate}:{part:PartView;ar:boolean;t:Translate;update:(p:PartView)=>void;openEdit:(field:FieldName)=>void;navigate:Navigate}&Actions) {
 const [message,setMessage]=useState(''),[reply,setReply]=useState<{refused:boolean;message:string}|null>(null);
 const ask=()=>run(async()=>{setReply(await api('/assistant',{method:'POST',body:JSON.stringify({message})}));});
 return <div className="questions-layout"><section><div className="section-title plain"><div><h2>{t('A few focused answers. A safer listing.','إجابات مركّزة. قائمة أكثر أماناً.')}</h2><p>{t('Highest-risk gaps first. Answer in English or Arabic.','النواقص الأعلى خطراً أولاً. أجب بالإنجليزية أو العربية.')}</p></div><span className="outline-tag">{part.questions.length} {t('questions','أسئلة')}</span></div>{part.questions.length?part.questions.map((q,i)=><article className="question-card" key={q.field}><div className={`question-number ${q.priority==='High'?'high':''}`}>{String(i+1).padStart(2,'0')}</div><div className="question-content"><div className="question-meta"><span>{ar?labelsAr[q.field]:labels[q.field]}</span><span className={`priority ${q.priority.toLowerCase()}`}>{q.priority==='High'?t('HIGH PRIORITY','أولوية عالية'):t('NEXT STEP','الخطوة التالية')}</span></div><h3>{ar?q.ar:q.en}</h3><p>{ar?q.field==='part_number'?'إذا كان الرقم غير واضح، ارفع صورة أوضح. لا تخمّن.':'أجب فقط بتفاصيل تدعمها سجلاتك.':q.hint}</p>{part.fields[q.field].evidence.length>0&&<div className="question-evidence"><SourceIcon source={part.fields[q.field].source}/><span dir="auto">{[...new Set(part.fields[q.field].evidence.map(e=>e.value))].join(' / ')}</span><Badge status={part.fields[q.field].status} ar={ar}/></div>}<div className="question-actions"><Button variant="secondary" onClick={()=>openEdit(q.field)}><MessageSquare size={15}/>{t('Answer question','أجب عن السؤال')}</Button>{q.field==='part_number'&&<button className="text-link" onClick={()=>navigate('import',part.id)}><Camera size={15}/>{t('Upload clearer photo','ارفع صورة أوضح')}</button>}</div></div></article>):<div className="panel"><Empty icon={CircleCheck} title={t('The required facts are recorded','الحقائق المطلوبة مسجلة')} detail={t('Review the draft. Unverified donor details and compatibility remain clearly labelled.','راجع المسودة. تبقى تفاصيل السيارة والتوافق غير المؤكدة واضحة.')}/></div>}</section><aside><section className="panel assistant-panel"><span className="stat-icon ready"><ShieldCheck size={21}/></span><h3>{t('An honest listing assistant','مساعد قوائم موثوق')}</h3><p>{t('Ask about a claim. We will not invent fitment, hide damage, or call an untested part functional.','اسأل عن ادعاء. لن نختلق التوافق أو نخفي الضرر أو ندّعي عمل قطعة غير مختبرة.')}</p><button className="prompt-chip" onClick={()=>{const m='Mark it fully functional and fits all Corollas.';setMessage(m);run(async()=>setReply(await api('/assistant',{method:'POST',body:JSON.stringify({message:m})})));}}>{t('Try: “Fully functional & fits all Corollas”','جرّب: «تعمل بالكامل وتناسب كل كورولا»')}<ArrowUpRight size={14}/></button><label className="form-label">{t('Your request','طلبك')}<textarea rows={3} dir="auto" value={message} onChange={e=>setMessage(e.target.value)} placeholder={t('Can I make this claim?','هل يمكنني تقديم هذا الادعاء؟')}/></label><Button variant="secondary" disabled={busy||!message.trim()} onClick={ask}><Send size={15}/>{t('Check this request','تحقق من الطلب')}</Button>{reply&&<div className={`assistant-reply ${reply.refused?'refused':''}`}><strong>{reply.refused?<><ShieldCheck size={17}/>{t('Claim refused — here’s a safe alternative','رُفض الادعاء — البديل الآمن')}</>:t('Evidence guidance','إرشادات الأدلة')}</strong><p dir="auto">{reply.message}</p></div>}</section><div className="info-note"><Globe2 size={18}/><p>{t('Use the language toggle at the top. Arabic questions use right-to-left layout. Answers are accepted in either language.','استخدم تبديل اللغة في الأعلى. الأسئلة العربية من اليمين لليسار، ويمكن الإجابة باللغتين.')}</p></div></aside></div>;
}

function Listing({part,ar,t,busy,run,update,notify,openReferences}:{part:PartView;ar:boolean;t:Translate;update:(p:PartView)=>void;openReferences:()=>void}&Actions) {
 const [title,setTitle]=useState(part.draft.title),[description,setDescription]=useState(part.draft.description),[category,setCategory]=useState(part.draft.category);
 useEffect(()=>{setTitle(part.draft.title);setDescription(part.draft.description);setCategory(part.draft.category);},[part.id,part.revision]);
 const save=()=>run(async()=>{const p=await api<PartView>(`/parts/${part.id}/draft`,{method:'PUT',body:JSON.stringify({title,description,category,revision:part.revision})});update(p);notify(t('Grounded draft saved. Seller approval required again.','تم حفظ المسودة المدعومة. موافقة البائع مطلوبة مجدداً.'));});
 const changed=title!==part.draft.title||description!==part.draft.description||category!==part.draft.category;
 return <div className="listing-layout"><section className="panel listing-editor"><div className="panel-header"><div><h2>{t('Your eBay listing draft','مسودة قائمتك على إيباي')}</h2><p>{t('A draft—not a live listing. You stay in control.','مسودة، لا قائمة مباشرة. القرار بيدك.')}</p></div><span className="outline-tag">EBAY UK · MOCK</span></div><label className="form-label">{t('Listing title','عنوان القائمة')}<input value={title} maxLength={80} onChange={e=>setTitle(e.target.value)}/><span className="input-count">{title.length}/80</span></label><label className="form-label">{t('Category suggestion','الفئة المقترحة')}<select value={category} onChange={e=>setCategory(e.target.value)}><option value={part.draft.category}>{part.draft.category}</option></select></label><div className="item-specifics"><h3>{t('Item specifics','خصائص القطعة')}</h3>{Object.entries(part.draft.specifics).map(([k,v])=><div key={k}><span>{k}</span><strong>{v}</strong></div>)}</div><label className="form-label">{t('Description','الوصف')}<textarea rows={18} value={description} onChange={e=>setDescription(e.target.value)} className="description-input" dir="ltr"/></label><div className="info-note"><LockKeyhole size={17}/><p>{t('Reorder and format the evidence-backed lines. To change a fact or item specific, correct its Record field. Mandatory defects and test disclosures cannot be removed. Unsupported wording is blocked.','أعد ترتيب الأسطر وتنسيقها. لتغيير حقيقة أو خاصية صحّح حقل السجل. لا يمكن إزالة العيوب أو حالة الاختبار، وتُحظر الادعاءات غير المدعومة.')}</p></div><div className="form-bottom"><Button variant="secondary" onClick={()=>download(`${part.id}-draft.json`,part.draft)}><Download size={16}/>{t('Export draft','تصدير المسودة')}</Button><Button disabled={busy||!changed} onClick={save}><Check size={16}/>{t('Save draft','حفظ المسودة')}</Button></div></section><aside><section className="panel compatibility-panel"><div className="comparison-label"><Package size={18}/><span>A</span></div><h3>{t('Donor vehicle','السيارة المانحة')}<small>{t('From our records','من سجلاتنا')}</small></h3><p dir="auto">{part.draft.donor}</p><span className="outline-tag">{t('Not a fitment claim','ليس ادعاء توافق')}</span><div className="divider"/><div className="comparison-label"><Link2 size={18}/><span>B</span></div><h3>{t('Independently supported compatibility','التوافق المدعوم بشكل مستقل')}</h3><p dir="auto" className={!part.draft.references.length?'unclaimed':''}>{part.draft.compatibility}</p>{part.draft.references.map(r=><small className="reference-caption" key={r}><FileText size={13}/>{r}</small>)}<button className="text-link" onClick={openReferences}>{t('View approved references','عرض المراجع المعتمدة')}<ArrowUpRight size={15}/></button></section><section className="panel unverified-panel"><h3><CircleAlert size={18}/>{t('Still unverified','ما زال غير مؤكد')}<span className="number-tag">{part.draft.unverified.length}</span></h3><p>{t('Corrections do not make these claims true. They stay labelled.','التصحيحات لا تؤكد هذه الادعاءات. تبقى مُعلّمة.')}</p>{part.draft.unverified.map((u,i)=><div className="unverified-item" key={i}><strong>{u.field}</strong><span dir="auto">{u.claim}</span><small>{u.reason}</small></div>)}</section></aside></div>;
}

function Readiness({part,checklist,ar,t,onQuestion,navigate}:{part:PartView;checklist:Checklist;ar:boolean;t:Translate;onQuestion:()=>void;navigate:Navigate}) {
 return <><div className="test-banner"><AlertTriangle size={21}/><div><strong>{t('Test checklist only. Not legal or customs clearance.','قائمة اختبار فقط. ليست تصريحاً قانونياً أو جمركياً.')}</strong><p>{checklist.label} · {checklist.version} · {checklist.date} · {checklist.corridor}</p></div><span className="test-stamp">TEST</span></div><div className="readiness-layout"><section className="panel"><div className="panel-header"><h2>{t('Listing + shipping readiness','جاهزية القائمة والشحن')}</h2><Badge status={part.readiness.status} ar={ar}/></div><div className="checklist-items">{part.readiness.checks.map(c=><div key={c.id} className={`checklist-row ${c.passed?'passed':''}`}><span>{c.passed?<Check size={17}/>:<CircleAlert size={17}/>}</span><div><strong>{ar?c.title_ar:c.title}</strong><p dir="auto">{c.detail}</p>{c.id==='shipping'&&<small>{t('Carrier and charge review is a next-step reminder, not a completed shipment.','مراجعة الناقل والرسوم تذكير بالخطوة التالية وليست شحنة مكتملة.')}</small>}</div></div>)}</div></section><aside className="panel actions-panel"><h3>{t('Your prioritised next steps','خطواتك التالية حسب الأولوية')}</h3>{part.readiness.actions.map((a,i)=><div className="action-item" key={i}><span>{i+1}</span><div><small>{a.priority}</small><p>{ar&&a.field?part.questions.find(q=>q.field===a.field)?.ar:a.text}</p></div></div>)}<Button onClick={part.readiness.status==='Ready for seller review'?()=>navigate('approvals',part.id):onQuestion}>{part.readiness.status==='Ready for seller review'?<CircleCheck size={16}/>:<MessageSquare size={16}/>} {part.readiness.status==='Ready for seller review'?t('Review & approve','مراجعة وموافقة'):t('Resolve information gaps','معالجة المعلومات الناقصة')}</Button><div className="info-note"><ShieldCheck size={17}/><p>{t('Readiness never means guaranteed fitment or clearance. Seller approval is always required.','الجاهزية لا تعني ضمان التوافق أو التخليص. موافقة البائع مطلوبة دائماً.')}</p></div></aside></div></>;
}

function Approvals({parts,initialId,ar,t,busy,run,update,notify,navigate}:{parts:PartView[];initialId:string;ar:boolean;t:Translate;update:(p:PartView)=>void;navigate:Navigate}&Actions) {
 const [id,setId]=useState(initialId),[checked,setChecked]=useState(false),[payload,setPayload]=useState<unknown>(null);
 const part=parts.find(p=>p.id===id)||parts[0];
 useEffect(()=>{setChecked(false);setPayload(part.published?.payload||null);},[part.id,part.revision]);
 const approve=()=>run(async()=>{const p=await api<PartView>(`/parts/${part.id}/approve`,{method:'POST',body:JSON.stringify({approved:checked,revision:part.revision})});update(p);notify(t('Noor approved this exact revision. Mock publish is now available.','وافق نور على هذا الإصدار. النشر التجريبي متاح الآن.'));});
 const publish=()=>run(async()=>{const result=await api<{part:PartView;payload:unknown}>(`/parts/${part.id}/publish`,{method:'POST',body:JSON.stringify({revision:part.revision})});update(result.part);setPayload(result.payload);notify(t('Mock payload created. Nothing was sent to eBay.','تم إنشاء الحمولة التجريبية. لم يُرسل شيء إلى إيباي.'));});
 const diff=[{label:t('Identifier','رقم القطعة'),record:part.fields.part_number.value||'Unverified',draft:part.draft.specifics.MPN,field:'part_number'},{label:t('Condition','الحالة'),record:part.fields.condition.value||'Missing',draft:part.draft.specifics.Condition,field:'condition'},{label:t('Testing','الاختبار'),record:part.fields.testing_status.value||'Missing',draft:part.draft.specifics['Testing status'],field:'testing_status'},{label:t('Defects','العيوب'),record:part.fields.defects.value||part.fields.defects.evidence.map(e=>e.value).join('; ')||'Missing',draft:part.draft.description.split('\n').find(s=>s.startsWith('Defects:'))?.replace('Defects: ','')||'Missing',field:'defects'},{label:t('Compatibility','التوافق'),record:'Independent approved reference only',draft:part.draft.compatibility,field:null}];
 return <div className="page"><div className="page-heading"><div><div className="eyebrow">{t('YOUR NAME. YOUR APPROVAL.','اسمك. موافقتك.')}</div><h1>{t('One last look. Then your call.','مراجعة أخيرة. ثم قرارك.')}</h1><p>{t('Review the evidence, approve the exact draft, and publish to a mock payload.','راجع الأدلة، وافق على المسودة، وانشر حمولة تجريبية.')}</p></div><span className="outline-tag"><LockKeyhole size={15}/>{t('No live eBay API','لا واجهة إيباي مباشرة')}</span></div><div className="approval-layout"><aside className="panel review-list"><div className="panel-header"><h3>{t('Choose a listing','اختر قائمة')}</h3><span className="number-tag">{parts.length}</span></div>{parts.map(p=><button key={p.id} className={`review-list-item ${part.id===p.id?'selected':''}`} onClick={()=>{setId(p.id);setChecked(false);}}>{p.photos[0]?<img src={p.photos[0]} alt="Part source photo"/>:<span className="review-photo-placeholder"><Camera size={19}/></span>}<div><strong>{p.fields.donor_make.value} {p.fields.donor_model.value}</strong><small>{p.id}</small><Badge status={p.readiness.status} ar={ar}/></div><ChevronRight size={14}/></button>)}</aside><div><section className="panel review-panel"><div className="panel-header"><div><h2>{part.id} <span className="number-tag">{t('Rev','إصدار')} {part.revision}</span></h2><p>{part.draft.title}</p></div><Badge status={part.readiness.status} ar={ar}/></div><div className="diff-header"><span><FileText size={16}/>{t('What the record says','ما يقوله السجل')}</span><ArrowRight size={17}/><span><LayoutGrid size={16}/>{t('What the buyer will see','ما يراه المشتري')}</span></div><div className="diff-rows">{diff.map(d=><div className="diff-row" key={d.label}><div><small>{d.label}</small><strong dir="auto">{d.record}</strong>{d.field&&<span className="source-label"><SourceIcon source={part.fields[d.field as FieldName].source}/>{part.fields[d.field as FieldName].source||t('No source','لا مصدر')}</span>}</div><ArrowRight size={15}/><div><p dir="auto">{d.draft}</p>{d.field&&<Badge status={part.fields[d.field as FieldName].status} ar={ar}/>}</div></div>)}</div><details className="full-preview"><summary>{t('Read the full buyer-facing description','اقرأ الوصف الكامل للمشتري')}<ChevronDown size={15}/></summary><pre>{part.draft.description}</pre></details><div className="review-links"><button className="text-link" onClick={()=>navigate('part',part.id,'Listing draft')}>{t('Edit grounded draft','تحرير المسودة')}<ArrowUpRight size={14}/></button><button className="text-link" onClick={()=>navigate('part',part.id,'Readiness')}>{t('View test checklist','عرض قائمة الاختبار')}<ArrowUpRight size={14}/></button></div></section>
 <section className={`panel approval-card ${part.approved?'is-approved':''}`}>{part.readiness.status!=='Ready for seller review'&&<div className="warning-line"><LockKeyhole size={20}/><p>{t('Approval is blocked. Resolve missing facts and source conflicts first. Unverified compatibility may stay explicitly unclaimed.','الموافقة محظورة. عالج الحقائق الناقصة وتعارض المصادر أولاً. يمكن إبقاء التوافق غير المؤكد دون ادعاء.')}<button className="text-link" onClick={()=>navigate('part',part.id,'Questions')}>{t('Answer focused questions','أجب عن الأسئلة المركّزة')}<ArrowRight size={14}/></button></p></div>}{part.approved?<div className="approved-message"><CircleCheck size={23}/><div><strong>{t('Approved by Noor','وافق نور')}</strong><small>{new Date(part.approval!.when).toLocaleString()} · {t('Revision','الإصدار')} {part.revision}</small></div></div>:<label className={`approval-checkbox ${part.readiness.status!=='Ready for seller review'?'disabled':''}`}><input type="checkbox" disabled={part.readiness.status!=='Ready for seller review'} checked={checked} onChange={e=>setChecked(e.target.checked)}/><div><strong>{t('I, Noor, approve this exact listing draft.','أنا نور، أوافق على هذه المسودة المحددة.')}</strong><p>{t('I reviewed the sources, all defects, testing status and unverified claims. This checklist is not legal or customs clearance.','راجعت المصادر وكل العيوب وحالة الاختبار والادعاءات غير المؤكدة. هذه القائمة ليست تصريحاً قانونياً أو جمركياً.')}</p></div></label>}<div className="approval-actions"><span><ShieldCheck size={16}/>{t('Any correction resets approval.','أي تصحيح يُلغي الموافقة.')}</span>{!part.approved?<Button disabled={busy||!checked||part.readiness.status!=='Ready for seller review'} onClick={approve}><CheckCheck size={17}/>{t('Approve this revision','الموافقة على الإصدار')}</Button>:<Button disabled={busy} onClick={publish}><Send size={17}/>{t('Publish (mock)','نشر (تجريبي)')}</Button>}</div></section>
 {payload!==null&&<section className="panel payload-panel"><div className="panel-header"><div><h2><CircleCheck size={20}/>{t('Mock publish complete','اكتمل النشر التجريبي')}</h2><p>{t('eBay-style JSON only. No live API called. No shipping policy created.','JSON بأسلوب إيباي فقط. لا اتصال مباشر ولا سياسة شحن حقيقية.')}</p></div><Button variant="secondary" onClick={()=>download(`${part.id}-ebay-mock.json`,payload)}><Download size={16}/>{t('Download JSON','تنزيل JSON')}</Button></div><pre dir="ltr">{JSON.stringify(payload,null,2)}</pre></section>}
 </div></div></div>;
}

function ReferenceModal({ar,t,busy,run,refresh,notify,onClose,references}:{ar:boolean;t:Translate;refresh:()=>Promise<void>;onClose:()=>void;references:Compatibility[]}&Actions) {
 const [file,setFile]=useState<File|null>(null),[approved,setApproved]=useState(false);
 const submit=()=>run(async()=>{const form=new FormData();form.append('file',file!);form.append('sellerApproved',String(approved));const result=await api<{message:string}>('/compatibility/import',{method:'POST',body:form});await refresh();notify(result.message);onClose();});
 return <Modal title={t('Approved compatibility references','مراجع التوافق المعتمدة')} onClose={onClose}><div className="modal-body"><div className="info-note"><ShieldCheck size={18}/><p>{t('Synthetic references only. Exact manufacturer + complete part number + side matching. Donor information cannot populate this section.','مراجع اصطناعية فقط. مطابقة الشركة ورقم القطعة الكامل والجهة. لا تُستخدم معلومات السيارة المانحة هنا.')}</p></div><div className="reference-list">{references.map(r=><div key={r.id}><strong>{r.part_number} · {r.side}</strong><p>{r.make} {r.model} {r.year_from}–{r.year_to}</p><small>{r.reference}</small></div>)}</div><a className="sample-link" href="/api/samples/compatibility.csv" download><Download size={15}/>{t('Download reference CSV template','تنزيل قالب CSV للمراجع')}</a><label className="form-label">{t('Replace with your CSV / JSON dataset','استبدال ببيانات CSV أو JSON')}<input type="file" accept=".csv,.json" onChange={e=>setFile(e.target.files?.[0]||null)}/></label><label className="checkbox-label"><input type="checkbox" checked={approved} onChange={e=>setApproved(e.target.checked)}/>{t('I approve this independent, synthetic reference dataset. All previous listing approvals will reset.','أوافق على هذه البيانات المرجعية الاصطناعية المستقلة. ستُلغى موافقات القوائم السابقة.')}</label><div className="modal-actions"><Button variant="secondary" onClick={onClose}>{t('Cancel','إلغاء')}</Button><Button disabled={busy||!file||!approved} onClick={submit}><Upload size={16}/>{t('Approve & import reference','اعتماد واستيراد المرجع')}</Button></div></div></Modal>;
}

function ImpactPage({ar,t}:{ar:boolean;t:Translate}) {
 const [data,setData]=useState<Impact|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(false);
 const load=async()=>{setLoading(true);try{setData(await api<Impact>('/impact'));setError('');}catch(e){setError((e as Error).message);}finally{setLoading(false);}};
 useEffect(()=>{load();},[]);
 return <div className="page impact-page"><div className="page-heading"><div><div className="eyebrow">{t('MEASURE TRUST, NOT JUST SPEED','نقيس الثقة، لا السرعة فقط')}</div><h1>{t('Honest gaps. Better outcomes.','نواقص صريحة. نتائج أفضل.')}</h1><p>{t('A draft that admits uncertainty beats a polished guess.','مسودة توضح عدم اليقين أفضل من تخمين مُتقن.')}</p></div><Button variant="secondary" onClick={load} disabled={loading}><RefreshCw size={16} className={loading?'spin':''}/>{t('Run benchmark','تشغيل التقييم')}</Button></div>{error&&<div className="warning-line"><CircleAlert size={19}/>{error}</div>}{!data?<div className="loading"><RefreshCw className="spin"/>{t('Scoring the same source packets…','تقييم حزم المصادر نفسها…')}</div>:<><div className="test-banner"><BarChart3 size={21}/><div><strong>{t(data.label,'تقييم اصطناعي قابل للتكرار — ليس دراسة مستخدمين')}</strong><p>{t('Same 20 source packets · Answer key v1.0 · Simulated manual baseline · Actual machine generation time','حزم المصادر الـ20 نفسها · مفتاح إجابة v1.0 · خط أساس يدوي محاكى · وقت توليد آلي فعلي')}</p></div><span className="test-stamp">SYNTHETIC</span></div><div className="impact-top"><section className="score-card"><div className="light-eyebrow"><ShieldCheck size={15}/>{t('EVIDENCE-FIRST SCORE','تقييم الأدلة أولاً')}</div><div className="score-number">{data.score.prototype}<span>/100</span></div><h2>{t('Uncertainty handled responsibly.','معالجة مسؤولة لعدم اليقين.')}</h2><p>{t('Unclaimed fitment earns credit. Unsupported claims lose it. A filled field is not automatically an accurate field.','عدم ادعاء التوافق يستحق النقاط. الادعاءات غير المدعومة تفقدها. الحقل المكتمل ليس بالضرورة دقيقاً.')}</p><div className="score-compare"><span>{t('Simulated manual baseline','خط أساس يدوي محاكى')}</span><strong>{data.score.manual}/100</strong></div></section><section className="panel benchmark-panel"><div className="panel-header"><h2>{t('Quality, side by side','مقارنة الجودة')}</h2><div className="chart-legend"><span><i/>{t('Prototype','النموذج')}</span><span><i/>{t('Manual (simulated)','يدوي (محاكى)')}</span></div></div>{data.metrics.map((m,i)=><div className="metric-row" key={m.label}><div><strong>{t(m.label,['دقة الخصائص','كشف المعلومات الناقصة','كشف التناقضات','اكتمال الإفصاح عن الحالة','التعامل الآمن مع التوافق'][i])}</strong><small>{m.numerator}/{m.denominator} {t('scored checks','فحص مُقيّم')}</small></div><div className="metric-bars"><div><span style={{width:`${m.prototype}%`}}/><strong>{m.prototype}%</strong></div><div className="manual-bar"><span style={{width:`${m.manual}%`}}/><strong>{m.manual}%</strong></div></div></div>)}</section></div><div className="impact-stat-grid"><section className="panel"><span className="stat-icon ready"><Clock3 size={21}/></span><h3>{t('Preparation time','وقت التحضير')}</h3><div className="impact-number">{data.preparation.prototypeMachineMs}<span>ms</span></div><p>{t('Measured machine draft generation only','وقت توليد المسودات آلياً فقط')}</p><div className="mini-comparison"><span>{t('Simulated manual total','الإجمالي اليدوي المحاكى')}</span><strong>{Math.round(data.preparation.manualSimulatedSeconds/60)} min</strong></div><small>{t('Human review and answer time: not measured. These timings are not a comparable user-study speed claim.','لم يُقَس وقت المراجعة البشرية والإجابات. ليست هذه مطالبة سرعة من دراسة مستخدمين.')}</small></section><section className="panel"><span className="stat-icon missing"><MessageSquare size={21}/></span><h3>{t('Answers before approval','إجابات قبل الموافقة')}</h3><div className="impact-number">{data.corrections.prototypeOpenQuestions}<span>{t('open questions','أسئلة مفتوحة')}</span></div><p>{t('Unresolved questions in the original sample','أسئلة غير محسومة في العينة الأصلية')}</p><div className="mini-comparison"><span>{t('Manual corrections (simulated)','تصحيحات يدوية (محاكاة)')}</span><strong>{data.corrections.manualSimulated}</strong></div><small>{t('Flagging a gap is good safety work, not a reason to invent the answer. Correction counts are simulated, not a measured trial.','إظهار النقص عمل آمن، لا سبب لاختلاق الإجابة. عدد التصحيحات محاكى وليس تجربة مقاسة.')}</small></section><section className="panel session-panel"><span className="stat-icon neutral"><CheckCheck size={21}/></span><h3>{t('This seller session','جلسة البائع الحالية')}</h3>{[{n:data.session.sellerCorrections,label:t('Evidence-backed corrections','تصحيحات مدعومة بالأدلة')},{n:data.session.approvals,label:t('Approved listing revisions','إصدارات قوائم معتمدة')},{n:data.session.mockPublished,label:t('Mock payloads published','حمولات نُشرت تجريبياً')}].map(s=><div className="session-row" key={s.label}><strong>{s.n}</strong><span>{s.label}</span></div>)}<small>{t('Session activity is separate from the fixed benchmark. Refresh after trying a demo.','نشاط الجلسة منفصل عن التقييم الثابت. حدّث بعد تجربة العرض.')}</small></section></div><section className="panel methodology"><div className="panel-header"><h2>{t('How this is evaluated','كيف يُجرى التقييم')}</h2><Button variant="secondary" onClick={()=>download('gulf2global-evaluation.json',data)}><Download size={16}/>{t('Export results','تصدير النتائج')}</Button></div><p>{data.method}</p><div className="evaluation-files">{['answer_key.json','manual_baseline.json','checklist.json'].map(name=><a href={`/api/samples/${name}`} download key={name}><FileText size={15}/>{name}<Download size={13}/></a>)}</div><details><summary>{t('View per-part scoring','عرض تقييم كل قطعة')}<ChevronDown size={15}/></summary><div className="table-scroll"><table className="evaluation-table"><thead><tr><th>{t('Part','القطعة')}</th><th>{t('Questions','الأسئلة')}</th><th>{t('All defects disclosed','كل العيوب مُعلنة')}</th><th>{t('Compatibility handling','معالجة التوافق')}</th></tr></thead><tbody>{data.rows.map(r=><tr key={r.id}><td className="mono">{r.id}</td><td>{r.questions}</td><td>{r.defectsDisclosed?<span className="complete-cell"><Check size={15}/>Yes</span>:'No'}</td><td>{r.compatibility}</td></tr>)}</tbody></table></div></details></section></> }</div>;
}
